// Entry detection that survives every runner AND subclass gates:
// `vite-node <script>.ts -- …` leaves the gate's flags in argv (a test
// runner importing this module does not), and the invoked script path in
// argv must be THIS module — a house gate importing this file carries the
// same flags, and only its own bootstrap may claim them.
export function bootstrapCli(gate: typeof Class, moduleUrl: string): void {
  const modulePath = fileURLToPath(moduleUrl).replaceAll('\\', '/');
  const cliArguments = process.argv.slice(2);
  const invokedAsCli =
    !process.env.VITEST &&
    process.argv.some((argument) => argument.endsWith('.ts') && modulePath.endsWith(argument.replaceAll('\\', '/').replace(/^\.\//, ''))) &&
    cliArguments.some((argument) => ['--source-root', '--test-glob', '--skip-list', '--list', '--prove', '--help', '-h'].includes(argument));
  if (invokedAsCli) void gate.main(cliArguments.filter((argument) => !argument.endsWith('.ts'))).then((code) => process.exit(code));
}

bootstrapCli(Class, import.meta.url);

